#!/usr/bin/env python3
import os
PROJECT = os.path.dirname(os.path.abspath(__file__))
HTML = os.path.join(PROJECT, 'public', 'index.html')
API  = os.path.join(PROJECT, 'api', 'index.py')
print("Geodetic Knife - Calibration Fix Script")
print("=" * 42)
with open(HTML, 'r', encoding='utf-8') as f:
    html = f.read()
fixed = 0
if '.cp-table' not in html:
    css = '\n/* Calibration Panel Styles */\n#calContainer{display:none;padding:16px}\n#calContainer.active{display:block}\n.cal-section{background:var(--card);border-radius:8px;padding:12px;margin-bottom:12px}\n.cal-section h4{margin:0 0 8px;color:var(--accent);font-size:14px}\n.cal-info{font-size:12px;color:var(--muted);margin-bottom:12px;line-height:1.5}\n.cp-table{width:100%;border-collapse:collapse;font-size:13px}\n.cp-table th{background:var(--border);padding:6px 4px;font-weight:600;text-align:center;white-space:nowrap}\n.cp-table td{padding:3px 2px;text-align:center;border-bottom:1px solid var(--border)}\n.cp-table input{width:100%;min-width:70px;background:var(--bg);color:var(--fg);border:1px solid var(--border);padding:4px 6px;border-radius:4px;font-size:12px}\n.cp-table .rm-btn{background:#5a2020;color:#faa;border:1px solid #733;padding:2px 8px;border-radius:4px;cursor:pointer;font-size:11px}\n.cp-table .rm-btn:hover{background:#733}\n.cal-actions{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}\n.cal-btn{padding:8px 16px;border:none;border-radius:6px;cursor:pointer;font-size:13px;font-weight:600;transition:background .2s}\n.cal-btn.primary{background:var(--accent);color:#fff}\n.cal-btn.primary:hover{filter:brightness(1.2)}\n.cal-btn.secondary{background:var(--border);color:var(--fg)}\n.cal-btn.secondary:hover{filter:brightness(1.3)}\n.cal-btn.danger{background:#5a2020;color:#faa}\n.cal-btn.danger:hover{background:#733}\n.cal-target{margin-bottom:12px;display:flex;align-items:center;gap:8px;font-size:13px}\n.cal-target select{background:var(--bg);color:var(--fg);border:1px solid var(--border);padding:4px 8px;border-radius:4px}\n.cal-results{display:none}\n.cal-results.visible{display:block}\n.cal-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px;margin-bottom:12px}\n.cal-stat{background:var(--card);border-radius:6px;padding:10px;text-align:center}\n.cal-stat .val{font-size:18px;font-weight:700;color:var(--accent)}\n.cal-stat .lbl{font-size:11px;color:var(--muted);margin-top:2px}\n.cal-params{margin-bottom:12px}\n.cal-params table{width:100%;border-collapse:collapse;font-size:12px}\n.cal-params th,.cal-params td{padding:5px 8px;border:1px solid var(--border);text-align:center}\n.cal-residuals{overflow-x:auto}\n.cal-residuals table{width:100%;border-collapse:collapse;font-size:11px}\n.cal-residuals th,.cal-residuals td{padding:4px 6px;border:1px solid var(--border);text-align:center}\n.cal-residuals .good{color:#5a5}\n.cal-residuals .warn{color:#aa5}\n.cal-residuals .bad{color:#a55}\n.cal-status{display:inline-block;padding:3px 10px;border-radius:12px;font-size:12px;font-weight:600}\n.cal-status.active{background:#2a5a2a;color:#5f5}\n.cal-status.inactive{background:#5a5a2a;color:#aa5}\n'
    html = html.replace('</style>', css + '</style>', 1)
    fixed += 1; print("[+] Injected calibration CSS")
else:
    print("[=] CSS already present")
if "switchTab('calibration')" not in html:
    tab_html = '    <button class="tab-btn" onclick="switchTab(\'calibration\')">&#9881; Calibrate</button>\n'
    idx = html.rfind('class="tab-btn"')
    if idx > 0:
        end = html.find('</button>', idx) + len('</button>')
        html = html[:end] + '\n' + tab_html + html[end:]
        fixed += 1; print("[+] Injected calibration tab button")
    else: print("[!] WARNING: Could not find tab button anchor")
else: print("[=] Tab button already present")
if 'id="calContainer"' not in html:
    container = '\n<div id="calContainer" class="panel">\n  <div class="cal-section">\n    <h4>Local Calibration &mdash; 7-Parameter Helmert Transformation</h4>\n    <div class="cal-info">\n      Provide pairs of known coordinates (WGS84 lat/lon + Grid easting/northing) to derive a custom\n      7-parameter Helmert transformation via weighted least-squares on ECEF differences.<br>\n      Minimum <b>3 points</b> required. Recommended <b>5&ndash;10+</b> for optimal accuracy.\n      <br><br>\n      Calibration status: <span id="calStatusBadge" class="cal-status inactive">Not calibrated</span>\n    </div>\n    <div class="cal-target">\n      <label>Target Grid:</label>\n      <select id="calTarget">\n        <option value="GNG" selected>GNG (Gold Coast Feet)</option>\n        <option value="GMG">GMG (Ghana Metre Grid)</option>\n      </select>\n      <span style="font-size:11px;color:var(--muted)">&mdash; Grid system of your known easting/northing values</span>\n    </div>\n  </div>\n  <div class="cal-section">\n    <h4>Control Points</h4>\n    <div style="overflow-x:auto">\n      <table class="cp-table" id="cpTable">\n        <thead><tr><th>#</th><th>Latitude</th><th>Longitude</th><th>H (m)</th><th>Easting</th><th>Northing</th><th></th></tr></thead>\n        <tbody id="cpBody"></tbody>\n      </table>\n    </div>\n    <div class="cal-actions">\n      <button class="cal-btn primary" onclick="addCP()">+ Add Point</button>\n      <button class="cal-btn secondary" onclick="loadSampleCP()">Load Sample (Accra)</button>\n      <button class="cal-btn secondary" onclick="loadCPFile()">Load CSV File</button>\n      <input type="file" id="cpFileInput" accept=".csv,.txt,.tsv" style="display:none" onchange="handleCPFile(event)">\n    </div>\n  </div>\n  <div class="cal-section cal-actions" style="padding:12px">\n    <button class="cal-btn primary" onclick="doCalibrate()">&#128295; Run Calibration</button>\n    <button class="cal-btn secondary" onclick="applyCal()">&#9989; Apply to Conversions</button>\n    <button class="cal-btn danger" onclick="clearCal()">&#128465; Clear Calibration</button>\n    <button class="cal-btn secondary" onclick="exportCal()">&#128229; Export Results</button>\n  </div>\n  <div id="calResults" class="cal-results">\n    <div class="cal-section"><h4>Statistics</h4><div class="cal-stats" id="calStats"></div></div>\n    <div class="cal-section"><h4>7-Parameter Helmert Coefficients</h4><div class="cal-params" id="calParams"></div></div>\n    <div class="cal-section"><h4>Residuals</h4><div class="cal-residuals" id="calResiduals"></div></div>\n  </div>\n</div>\n'
    html = html.replace('<script>', container + '\n<script>', 1)
    fixed += 1; print("[+] Injected calibration panel HTML")
else: print("[=] Container already present")
if 'function doCalibrate()' not in html:
    js = '\n/* ========== Calibration Module ========== */\nvar calState = {towgs84:null, params:null, stats:null};\n(function initCal(){\n  var saved = localStorage.getItem(\'geodetic_cal\');\n  if(saved){\n    try { calState = JSON.parse(saved); updateCalBadge(); patchFetch(); }\n    catch(e){ localStorage.removeItem(\'geodetic_cal\'); }\n  }\n})();\nfunction updateCalBadge(){\n  var b = document.getElementById(\'calStatusBadge\');\n  if(!b) return;\n  if(calState.towgs84){\n    b.className = \'cal-status active\';\n    b.textContent = \'Active \\u2014 \' + calState.stats.rms_combined.toFixed(3) + \' m RMS\';\n  } else {\n    b.className = \'cal-status inactive\';\n    b.textContent = \'Not calibrated\';\n  }\n}\nvar cpCounter = 0;\nfunction addCP(lat, lon, h, e, n){\n  cpCounter++;\n  var tr = document.createElement(\'tr\');\n  tr.innerHTML = \'<td>\' + cpCounter + \'</td>\'\n    + \'<td><input type="text" placeholder="5.6037" value="\' + (lat||\'\') + \'" class="cp-lat"></td>\'\n    + \'<td><input type="text" placeholder="-0.1870" value="\' + (lon||\'\') + \'" class="cp-lon"></td>\'\n    + \'<td><input type="text" placeholder="0" value="\' + (h||\'\') + \'" class="cp-h"></td>\'\n    + \'<td><input type="text" placeholder="easting" value="\' + (e||\'\') + \'" class="cp-e"></td>\'\n    + \'<td><input type="text" placeholder="northing" value="\' + (n||\'\') + \'" class="cp-n"></td>\'\n    + \'<td><button class="rm-btn" onclick="rmCP(this)">&#10005;</button></td>\';\n  document.getElementById(\'cpBody\').appendChild(tr);\n}\nfunction rmCP(btn){ btn.closest(\'tr\').remove(); }\nfunction loadSampleCP(){\n  var pts = [\n    [5.6037, -0.1870, 0, 710232.456, 620345.789],\n    [5.5512, -0.2234, 0, 706891.123, 614567.234],\n    [5.6289, -0.0912, 0, 715678.901, 627890.456],\n    [5.5890, -0.3456, 0, 702456.789, 611234.567],\n    [5.6501, -0.1543, 0, 712345.678, 625678.123]\n  ];\n  document.getElementById(\'cpBody\').innerHTML = \'\';\n  cpCounter = 0;\n  pts.forEach(function(p){ addCP(p[0], p[1], p[2], p[3], p[4]); });\n}\nfunction loadCPFile(){ document.getElementById(\'cpFileInput\').click(); }\nfunction handleCPFile(ev){\n  var file = ev.target.files[0];\n  if(!file) return;\n  var reader = new FileReader();\n  reader.onload = function(e){\n    var lines = e.target.result.split(\'\\n\');\n    var delim = lines[0].indexOf(\'\\t\') > -1 ? \'\\t\' : \',\';\n    document.getElementById(\'cpBody\').innerHTML = \'\';\n    cpCounter = 0;\n    lines.forEach(function(line){\n      var cols = line.trim().split(delim).map(function(s){ return s.trim(); });\n      if(cols.length >= 4 && !isNaN(parseFloat(cols[0])) && !isNaN(parseFloat(cols[1]))){\n        addCP(cols[0], cols[1], cols[2] || \'0\', cols[3], cols[4] || \'\');\n      }\n    });\n  };\n  reader.readAsText(file); ev.target.value = \'\';\n}\nfunction doCalibrate(){\n  var rows = document.querySelectorAll(\'#cpBody tr\');\n  if(rows.length < 3){ alert(\'Need at least 3 control points\'); return; }\n  var pts = [];\n  rows.forEach(function(r){\n    var lat = r.querySelector(\'.cp-lat\').value;\n    var lon = r.querySelector(\'.cp-lon\').value;\n    var h   = r.querySelector(\'.cp-h\').value;\n    var e   = r.querySelector(\'.cp-e\').value;\n    var n   = r.querySelector(\'.cp-n\').value;\n    if(lat && lon && e && n && !isNaN(parseFloat(lat)))\n      pts.push({lat:parseFloat(lat),lon:parseFloat(lon),h:parseFloat(h)||0,easting:parseFloat(e),northing:parseFloat(n)});\n  });\n  if(pts.length < 3){ alert(\'Need at least 3 valid control points\'); return; }\n  var tgt = document.getElementById(\'calTarget\').value;\n  fetch(\'/api/calibrate\',{\n    method:\'POST\',headers:{\'Content-Type\':\'application/json\'},\n    body:JSON.stringify({points:pts,target:tgt})\n  }).then(function(r){return r.json();}).then(function(d){\n    if(d.error){alert(\'Calibration error: \'+d.error);return;}\n    calState={towgs84:d.towgs84,params:d.params,stats:d.statistics};\n    showCalResults(d);\n  }).catch(function(e){alert(\'Network error: \'+e.message);});\n}\nfunction showCalResults(d){\n  document.getElementById(\'calResults\').classList.add(\'visible\');\n  var s=d.statistics;\n  document.getElementById(\'calStats\').innerHTML=\n    \'<div class="cal-stat"><div class="val">\'+s.num_points+\'</div><div class="lbl">Points Used</div></div>\'\n    +\'<div class="cal-stat"><div class="val">\'+s.rms_e.toFixed(4)+\' m</div><div class="lbl">RMS Easting</div></div>\'\n    +\'<div class="cal-stat"><div class="val">\'+s.rms_n.toFixed(4)+\' m</div><div class="lbl">RMS Northing</div></div>\'\n    +\'<div class="cal-stat"><div class="val">\'+s.rms_combined.toFixed(4)+\' m</div><div class="lbl">RMS Combined</div></div>\'\n    +\'<div class="cal-stat"><div class="val">\'+s.scale_ppm.toFixed(2)+\'</div><div class="lbl">Scale (ppm)</div></div>\'\n    +\'<div class="cal-stat"><div class="val">\'+s.degrees_of_freedom+\'</div><div class="lbl">DoF</div></div>\';\n  var p=d.params;\n  var a2s=function(r){return(r*180/Math.PI*3600).toFixed(4);};\n  document.getElementById(\'calParams\').innerHTML=\n    \'<table><tr><th>Parameter</th><th>Value</th><th>Unit</th></tr>\'\n    +\'<tr><td>TX</td><td>\'+p.tx.toFixed(4)+\'</td><td>metres</td></tr>\'\n    +\'<tr><td>TY</td><td>\'+p.ty.toFixed(4)+\'</td><td>metres</td></tr>\'\n    +\'<tr><td>TZ</td><td>\'+p.tz.toFixed(4)+\'</td><td>metres</td></tr>\'\n    +\'<tr><td>RX</td><td>\'+a2s(p.rx)+\'</td><td>arc-seconds</td></tr>\'\n    +\'<tr><td>RY</td><td>\'+a2s(p.ry)+\'</td><td>arc-seconds</td></tr>\'\n    +\'<tr><td>RZ</td><td>\'+a2s(p.rz)+\'</td><td>arc-seconds</td></tr>\'\n    +\'<tr><td>Scale</td><td>\'+(p.scale*1e6).toFixed(4)+\'</td><td>ppm</td></tr></table>\';\n  var rh=\'<table><tr><th>#</th><th>Lat</th><th>Lon</th><th>E Act</th><th>N Act</th><th>E Pred</th><th>N Pred</th><th>dE(m)</th><th>dN(m)</th><th>d(m)</th></tr>\';\n  d.residuals.forEach(function(r){\n    var rc=r.res_combined,cls=rc<0.1?\'good\':rc<0.5?\'warn\':\'bad\';\n    rh+=\'<tr><td>\'+r.point+\'</td><td>\'+r.lat+\'</td><td>\'+r.lon+\'</td><td>\'+r.e_actual+\'</td><td>\'+r.n_actual+\'</td><td>\'+r.e_predicted+\'</td><td>\'+r.n_predicted+\'</td><td class="\'+cls+\'">\'+r.res_e+\'</td><td class="\'+cls+\'">\'+r.res_n+\'</td><td class="\'+cls+\'">\'+r.res_combined+\'</td></tr>\';\n  });\n  rh+=\'</table>\';\n  document.getElementById(\'calResiduals\').innerHTML=rh;\n}\nfunction applyCal(){\n  if(!calState.towgs84){alert(\'No calibration results. Run calibration first.\');return;}\n  localStorage.setItem(\'geodetic_cal\',JSON.stringify(calState));\n  patchFetch(); updateCalBadge();\n  alert(\'Calibration applied! All conversions now use the custom 7-param Helmert.\\n\\nRMS: \'+calState.stats.rms_combined.toFixed(4)+\' m\');\n}\nfunction clearCal(){\n  if(!confirm(\'Clear calibration? Conversions will revert to Molodensky 3-param.\')) return;\n  calState={towgs84:null,params:null,stats:null};\n  localStorage.removeItem(\'geodetic_cal\');\n  updateCalBadge();\n  document.getElementById(\'calResults\').classList.remove(\'visible\');\n  alert(\'Calibration cleared.\');\n}\nfunction exportCal(){\n  if(!calState.stats){alert(\'No results to export\');return;}\n  var s=calState.stats,p=calState.params;\n  var a2s=function(r){return(r*180/Math.PI*3600).toFixed(4);};\n  var txt=\'Geodetic Knife - Calibration Report\\n====================================\\n\\nStatistics:\\n  Points: \'+s.num_points+\'\\n  RMS E: \'+s.rms_e+\' m\\n  RMS N: \'+s.rms_n+\' m\\n  RMS Combined: \'+s.rms_combined+\' m\\n  Scale: \'+s.scale_ppm+\' ppm\\n\\nParameters:\\n  TX: \'+p.tx.toFixed(4)+\' m\\n  TY: \'+p.ty.toFixed(4)+\' m\\n  TZ: \'+p.tz.toFixed(4)+\' m\\n  RX: \'+a2s(p.rx)+\'"\\n  RY: \'+a2s(p.ry)+\'"\\n  RZ: \'+a2s(p.rz)+\'"\\n  Scale: \'+(p.scale*1e6).toFixed(4)+\' ppm\\n\\nPROJ towgs84:\\n  \'+s.towgs84+\'\\n\';\n  var blob=new Blob([txt],{type:\'text/plain\'});\n  var a=document.createElement(\'a\');\n  a.href=URL.createObjectURL(blob);\n  a.download=\'calibration_report.txt\';\n  a.click();\n}\nfunction patchFetch(){\n  if(window._origFetch) return;\n  window._origFetch=window.fetch;\n  window.fetch=function(url,opts){\n    if(calState.towgs84 && opts && opts.body){\n      try{\n        var parsed=JSON.parse(opts.body);\n        if(parsed.mode||(parsed.points&&parsed.points.length)){\n          parsed.calibration={towgs84:calState.towgs84};\n          opts.body=JSON.stringify(parsed);\n        }\n      }catch(e){}\n    }\n    return window._origFetch.call(this,url,opts);\n  };\n  if(!window._origXHROpen){\n    var origOpen=XMLHttpRequest.prototype.open;\n    var origSend=XMLHttpRequest.prototype.send;\n    XMLHttpRequest.prototype.open=function(method,url){\n      this._calUrl=url;\n      return origOpen.apply(this,arguments);\n    };\n    XMLHttpRequest.prototype.send=function(body){\n      if(calState.towgs84 && body && this._calUrl && this._calUrl.indexOf(\'/api/\')>-1){\n        try{\n          var parsed=JSON.parse(body);\n          if(parsed.mode||(parsed.points&&parsed.points.length)){\n            parsed.calibration={towgs84:calState.towgs84};\n            body=JSON.stringify(parsed);\n          }\n        }catch(e){}\n      }\n      return origSend.call(this,body);\n    };\n    window._origXHROpen=true;\n  }\n}\nvar _origSwitchTab = typeof switchTab !== \'undefined\' ? switchTab : function(){};\nwindow.switchTab = function(tab){\n  document.querySelectorAll(\'.tab-btn\').forEach(function(btn){\n    var oc=btn.getAttribute(\'onclick\')||\'\';\n    btn.classList.toggle(\'active\',oc.indexOf("\'"+tab+"\'")>-1);\n  });\n  var cal=document.getElementById(\'calContainer\');\n  if(tab===\'calibration\'){\n    document.querySelectorAll(\'.panel\').forEach(function(p){p.style.display=\'none\';});\n    if(cal){cal.style.display=\'block\';cal.classList.add(\'active\');}\n    return;\n  }\n  if(cal){cal.style.display=\'none\';cal.classList.remove(\'active\');}\n  _origSwitchTab(tab);\n};\n'
    html = html.replace('</script>', js + '</script>', 1)
    fixed += 1; print("[+] Injected calibration JavaScript")
else: print("[=] JavaScript already present")
with open(HTML, 'w', encoding='utf-8') as f:
    f.write(html)
with open(API, 'r', encoding='utf-8') as f:
    api = f.read()
if '/api/calibration_status' not in api:
    ep = '\n\n@app.route("/api/calibration_status", methods=["GET"])\ndef calibration_status():\n    return jsonify({"status":"available","method":"7-param Helmert","min_points":3,"max_points":50})\n'
    api = api.replace('@app.route("/api/elevation"', ep + '@app.route("/api/elevation"')
    with open(API, 'w', encoding='utf-8') as f:
        f.write(api)
    fixed += 1; print("[+] Added /api/calibration_status endpoint")
else: print("[=] API endpoint already present")
print(); print("=" * 42); print("Done. " + str(fixed) + " fix(es) applied.")
if fixed == 0: print("All injections present - no changes needed.")
print(); print("Next steps:"); print("  git add -A"); print("  git commit -m \"Fix calibration: complete injections + status endpoint\""); print("  git push origin main")
